contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address receiver) public {
        // restrict to admissible domain: amount > 0, receiver can be anything including zero address
        vm.assume(amount > 0);
        // ensure contract starts with clean state
        // deploy a fresh C for each run to isolate state, but setUp already does that once.
        // We need owner to call sendTo; owner is deployer (this contract).
        // We'll send Ether from this contract (owner) to c.sendTo.
        vm.deal(address(this), amount);
        uint256 balanceBefore = address(c).balance;
        bool ok;
        try c.sendTo{value: amount}(receiver, amount) { ok = true; } catch { ok = false; }
