        // The only case where balance decreases is when transfer to zero address burns funds without revert.
        // So invariant: balanceAfter >= balanceBefore for any admissible input on the reference contract.
        // On buggy contract, when receiver == address(0), the transfer succeeds but burns ETH, so balanceAfter < balanceBefore.
        assertTrue(balanceAfter >= balanceBefore);
    }
}

