        // So if it succeeded, that means sender != owner (in correct version).
        // In the buggy version, non-owner calls revert, so this would fail.
        // We assert: if the call succeeded (i.e., sender is non-owner and correct succeeds),
        // then the buggy version would revert, so this test detects the bug.
        assertTrue(ok);
    }
