pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address receiver, uint256 amount) public {
        vm.assume(receiver != address(0));
        vm.assume(amount > 0);
        vm.assume(caller != address(0));
        vm.deal(caller, amount + 1 ether);

        bool origOk;
        vm.prank(caller);
        try c.sendTo{value: amount}(receiver, amount) { origOk = true; } catch { origOk = false; }

        // The invariant: success of sendTo differs between the correct and the buggy contract
        // because they have opposite owner checks. Since the fuzzer cannot directly call
        // the buggy contract, we simulate it by comparing behavior of two calls:
        // In the correct contract, sendTo succeeds if and only if caller != owner.
        // In the buggy contract, sendTo succeeds if and only if caller == owner.
        // Thus, for any caller, exactly one of the two would succeed.
        // We test this by checking that origOk == (caller != c.owner()).
        // The buggy contract would have origOk == (caller == c.owner()) for the same inputs,
        // breaking the invariant that origOk == (caller != owner).
        assertTrue(origOk == (caller != c.owner()));
    }
}

